fl.source:
import io { println }

enum Shape {
    Circle,
    Square,
    Triangle,
}

fn sides(s: Shape) -> Int {
    match s {
        Shape::Circle => 0,
        Shape::Square => 4,
    }
}

fn main() {
    println("{sides(Shape::Triangle)}")
}

