    println!("{}", sides(Shape::Triangle));
}

ts.source:
type Shape = "circle" | "square" | "triangle";

function sides(s: Shape): number {
    switch (s) {
        case "circle": return 0;
        case "square": return 4;
    }
}

console.log(sides("triangle"));

